import React, { useState, useEffect } from 'react';
import '../styles/DevNoticeModal.css';

const DevNoticeModal = ({ isOpen, onClose }) => {
  const [dontShowAgain, setDontShowAgain] = useState(false);
  const [isRendered, setIsRendered] = useState(false);
  
  // Untuk penanganan mounting/unmounting dengan animasi
  useEffect(() => {
    if (isOpen) {
      // Mencegah scroll dan tambahkan class untuk styling
      document.body.classList.add('modal-open');
      document.documentElement.style.overflow = 'hidden';
      document.body.style.overflow = 'hidden';
      
      // Set rendered state setelah delay singkat untuk memastikan DOM siap
      const timer = setTimeout(() => {
        setIsRendered(true);
      }, 50);
      
      return () => clearTimeout(timer);
    } else {
      // Kembalikan ke normal
      document.body.classList.remove('modal-open');
      document.documentElement.style.overflow = 'auto';
      document.body.style.overflow = 'auto';
      setIsRendered(false);
    }
  }, [isOpen]);
  
  // Jika tidak open, jangan render apapun
  if (!isOpen) return null;
  
  const handleClose = () => {
    onClose(dontShowAgain);
  };

  return (
    <div className={`dev-notice-overlay ${isRendered ? 'visible' : ''}`}>
      <div className={`dev-notice-modal ${isRendered ? 'visible' : ''}`}>
        <div className="dev-notice-header">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path>
            <line x1="12" y1="9" x2="12" y2="13"></line>
            <line x1="12" y1="17" x2="12.01" y2="17"></line>
          </svg>
          <h2>Perhatian</h2>
        </div>
        <div className="dev-notice-content">
          <p>Website <strong>StockAdvice</strong> masih dalam tahap pengembangan dan perbaikan.</p>
          <p>Beberapa fitur mungkin belum berfungsi dengan sempurna atau masih dalam proses implementasi.</p>
          <p>Terima kasih atas pengertian dan kesabaran Anda.</p>
        </div>

        <div className="dev-notice-checkbox">
          <input 
            type="checkbox" 
            id="dontShowAgain" 
            checked={dontShowAgain}
            onChange={(e) => setDontShowAgain(e.target.checked)} 
          />
          <label htmlFor="dontShowAgain">Jangan tampilkan notifikasi ini lagi</label>
        </div>
        
        <button className="dev-notice-button" onClick={handleClose}>
          Saya Mengerti
        </button>
      </div>
    </div>
  );
};

export default DevNoticeModal;
